<?php
declare(strict_types=1);
$music=json_decode(file_get_contents(__DIR__.'/audio/generation-manifest.json'),true,32,JSON_THROW_ON_ERROR);
$effects=json_decode(file_get_contents(__DIR__.'/audio/effects/generation-manifest.json'),true,32,JSON_THROW_ON_ERROR);
function musicEscape(string $s): string {return htmlspecialchars($s,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><base href="../"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The First Courtyard · Soundtrack</title><link rel="stylesheet" href="adventure/world.css?v=<?=filemtime(__DIR__.'/world.css')?>"><style>main{max-width:1100px;padding-bottom:60px}.music-intro{max-width:700px;line-height:1.8;color:var(--muted)}.music-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:30px}.music-track{padding:23px;background:#fff8e9;border:1px solid var(--line);border-radius:12px}.music-track h2{font-size:22px;font-weight:500;margin:8px 0 15px}.music-track audio{width:100%;display:block}.music-track p{font-size:12px;color:var(--muted)}@media(max-width:700px){.music-list{grid-template-columns:1fr}.world-header{flex-direction:column;align-items:start}.music-track{padding:18px}}</style></head><body><header class="world-header"><a class="brand" href="adventure/"><span class="brand-sun">☀</span><span><small>EL’S INVITATION</small><strong>Music of the First Courtyard</strong></span></a><a href="adventure/">Return to your adventure →</a></header><main><span class="eyebrow">SEVEN PLACES · FOUR CHALLENGERS</span><h1>Every place has a melody</h1><p class="music-intro">Lyres, reed winds, plucked lutes, and hand drums accompany your journey through Sumer. In the adventure, enable Music in the lower-right corner; themes follow your travels and your opponent, with soft transitions between them. <a href="adventure/soundtrack.php#effects">Listen to combat effects ↓</a></p><div class="music-list"><?php foreach($music['tracks'] as $i=>$track): ?><article class="music-track"><span class="eyebrow"><?= $i<7?'EXPLORATION':'CHAMPION' ?> · <?=musicEscape(ucwords(str_replace('-',' ',$track['id'])))?></span><h2><?=musicEscape($track['title'])?></h2><audio controls preload="metadata" aria-label="<?=musicEscape($track['title'])?>"><source src="adventure/audio/<?=musicEscape($track['file'])?>" type="audio/mpeg"></audio><p><?= $i<7?'A place to explore, listen, and learn.':'A theme for a challenger worth remembering.' ?></p></article><?php endforeach; ?></div><section id="effects"><h1 style="margin-top:45px">The sound of an exchange</h1><p class="music-intro">Twenty-three tactile effects accompany cards, burns, impacts, armor, and the outcome of a fight. Effects have their own volume and mute in the game’s Sound settings. <a href="adventure/effect-pilot.php">Compare the revised foley pilot →</a></p><div class="music-list"><?php foreach($effects['sounds'] as $effect): ?><article class="music-track"><span class="eyebrow">COMBAT EFFECT</span><h2><?=musicEscape(ucwords(str_replace('-',' ',$effect['id'])))?></h2><audio controls preload="metadata" aria-label="<?=musicEscape($effect['id'])?>"><source src="adventure/audio/effects/<?=musicEscape($effect['file'])?>" type="audio/mpeg"></audio></article><?php endforeach; ?></div></section></main><script>document.addEventListener('play',e=>{for(const audio of document.querySelectorAll('audio'))if(audio!==e.target)audio.pause();},true);</script></body></html>
